    assert(named_empty_field->textContent() == "S");
    editable_input.onKeyDown(0, "T", false, false, false);
    assert(editable_input.processInputEvents());
    assert(named_empty_field->textContent() == "ST");
    assert(named_empty_field->name() == "named_empty_field");

    auto authored_text_chunk = std::make_shared<CastMemberChunk>(nullptr,
                                                               ChunkId(401),
                                                               MemberType::Text,
                                                               0,
                                                               0,
                                                               std::vector<std::uint8_t>{},
                                                               std::vector<std::uint8_t>{},
                                                               "authored_field_text",
                                                               0,
                                                               0,
                                                               0);
    auto authored_text_field = std::make_shared<CastMember>(0, 1, 401, authored_text_chunk);
    const_cast<std::map<int, std::shared_ptr<CastMember>>&>(editable_cast->runtimeMembers())[401] = authored_text_field;
    auto authored_text_state = editable_renderer.spriteRegistry().getOrCreateDynamic(21);
    authored_text_state->setDynamicMember(1, authored_text_field->memberNum());
