    assert(editable_state.keyboardFocusSprite() == 21);
    editable_input.onKeyDown(0, "A", false, false, false);
    assert(editable_input.processInputEvents());
    assert(authored_text_field->textContent() == "A");

    auto old_score_text_field = editable_cast->createDynamicMember("text");
    old_score_text_field->setName("old_score_text_field");
    auto old_score_field_data = ScoreChunk::ChannelData::empty();
    old_score_field_data.sprite_type = 1;
    old_score_field_data.ink = libreshockwave::id::code(InkMode::BACKGROUND_TRANSPARENT);
    old_score_field_data.cast_lib = 1;
    old_score_field_data.cast_member = old_score_text_field->memberNum();
    old_score_field_data.pos_x = 50;
    old_score_field_data.pos_y = 160;
    old_score_field_data.width = 80;
    old_score_field_data.height = 18;
    auto old_score_text_state = editable_renderer.spriteRegistry().getOrCreate(18, old_score_field_data);
    old_score_text_state->setDynamicMember(1, old_score_text_field->memberNum());
    editable_renderer.setLastBakedSprites({
        RenderSprite(18, 50, 160, 80, 18, 5, true, SpriteType::Text, nullptr, old_score_text_field, 0, 0, false, false,
                     libreshockwave::id::code(InkMode::BACKGROUND_TRANSPARENT), 100, false, false, nullptr, false),
    });
    editable_input.onMouseDown(55, 165);
    assert(editable_input.processInputEvents());
    assert(editable_state.keyboardFocusSprite() == 0);
    editable_dispatcher.setRespondsPredicate([mouse_and_key_handlers](const EventTarget& target,
                                                                   std::string_view handler) {
        return target.kind == EventTargetKind::ScriptInstance &&
               mouse_and_key_handlers.contains(std::string(handler));
    });
    old_score_text_state->setScriptInstanceList({Datum::scriptInstance("old-score-field-key-handler")});
    editable_input.onMouseDown(55, 165);
    assert(editable_input.processInputEvents());
    assert(editable_state.keyboardFocusSprite() == 18);
    editable_input.onKeyDown(0, "V", false, false, false);
