    class PlayerFacadeDebugController final : public DebugControllerApi {
    public:
        void setGlobalsSnapshot(std::map<std::string, Datum> globals) override {
            globals_snapshot = std::move(globals);
        }

        void setLocalsSnapshot(std::map<std::string, Datum> locals) override {
            locals_snapshot = std::move(locals);
        }

        [[nodiscard]] bool isAwaitingStepContinuation() const override { return false; }
        void reset() override { ++reset_count; }
        [[nodiscard]] bool isPaused() const override { return paused; }
        [[nodiscard]] DebugState state() const override { return debug_state; }
        [[nodiscard]] std::optional<DebugSnapshot> currentSnapshot() const override { return snapshot; }
        void stepInto() override { debug_state = DebugState::Stepping; }
        void stepOver() override { debug_state = DebugState::Stepping; }
        void stepOut() override { debug_state = DebugState::Stepping; }
        void continueExecution() override { debug_state = DebugState::Running; }
        void pause() override {
            paused = true;
            debug_state = DebugState::Paused;
        }

        [[nodiscard]] bool toggleBreakpoint(int script_id, std::string handler_name, int offset) override {
            return breakpoint_manager_.toggleBreakpoint(script_id, std::move(handler_name), offset).has_value();
        }

        void clearAllBreakpoints() override { breakpoint_manager_.clearAll(); }

        [[nodiscard]] bool hasBreakpoint(int script_id, const std::string& handler_name, int offset) const override {
            return breakpoint_manager_.hasBreakpoint(script_id, handler_name, offset);
        }

        [[nodiscard]] std::optional<Breakpoint> getBreakpoint(int script_id,
                                                              const std::string& handler_name,
                                                              int offset) const override {
            return breakpoint_manager_.getBreakpoint(script_id, handler_name, offset);
        }

        [[nodiscard]] BreakpointManager& breakpointManager() override { return breakpoint_manager_; }
        [[nodiscard]] const BreakpointManager& breakpointManager() const override { return breakpoint_manager_; }
        [[nodiscard]] std::string serializeBreakpoints() const override { return breakpoint_manager_.serialize(); }
        void deserializeBreakpoints(std::string data) override { breakpoint_manager_.deserialize(std::move(data)); }

        [[nodiscard]] WatchExpression addWatchExpression(std::string expression) override {
            auto watch = WatchExpression::create(std::move(expression));
            watches.push_back(watch);
            return watch;
        }

        [[nodiscard]] bool removeWatchExpression(const std::string& id) override {
            const auto before = watches.size();
            watches.erase(std::remove_if(watches.begin(),
                                         watches.end(),
                                         [&id](const WatchExpression& watch) {
                                             return watch.id == id;
                                         }),
                          watches.end());
            return watches.size() != before;
        }

        [[nodiscard]] std::vector<WatchExpression> watchExpressions() const override { return watches; }
        [[nodiscard]] std::vector<WatchExpression> evaluateWatchExpressions() override { return watches; }
        void clearWatchExpressions() override { watches.clear(); }
        [[nodiscard]] std::vector<CallFrame> callStackSnapshot() const override { return call_stack; }

        [[nodiscard]] bool needsInstructionTrace() const override { return instruction_trace; }

        void onHandlerEnter(const HandlerInfo& info) override {
            ++handler_enter_count;
            last_handler_name = info.handler_name;
        }

        void onHandlerExit(const HandlerInfo&, const Datum& return_value) override {
            ++handler_exit_count;
            last_return_value = return_value;
        }

        void onInstruction(const InstructionInfo& info) override {
            ++instruction_count;
            last_opcode = info.opcode;
        }

        void onVariableSet(std::string_view type, std::string_view name, const Datum& value) override {
            ++variable_set_count;
            last_variable_set = std::string(type) + ":" + std::string(name);
            last_variable_set_value = value;
        }

        void onError(std::string_view message, std::string_view error) override {
            ++error_count;
            last_error = std::string(message) + "|" + std::string(error);
        }

        void onDebugMessage(std::string_view message) override {
            ++debug_message_count;
            last_debug_message = std::string(message);
        }

        std::map<std::string, Datum> globals_snapshot;
        std::map<std::string, Datum> locals_snapshot;
        std::optional<DebugSnapshot> snapshot;
        std::vector<WatchExpression> watches;
        std::vector<CallFrame> call_stack;
        BreakpointManager breakpoint_manager_;
        bool instruction_trace = true;
        bool paused = false;
        DebugState debug_state = DebugState::Running;
        int reset_count = 0;
        int handler_enter_count = 0;
        int handler_exit_count = 0;
        int instruction_count = 0;
        int variable_set_count = 0;
        int error_count = 0;
        int debug_message_count = 0;
        std::string last_handler_name;
        std::string last_opcode;
        std::string last_variable_set;
        std::string last_error;
        std::string last_debug_message;
        Datum last_variable_set_value = Datum::voidValue();
        Datum last_return_value = Datum::voidValue();
    };
