    auto wait_until = [](const auto& predicate) {
        for (int attempt = 0; attempt < 200; ++attempt) {
            if (predicate()) {
                return true;
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(5));
        }
        return predicate();
    };

