    class PlayerFacadeNetProvider final : public NetProvider {
    public:
        [[nodiscard]] int preloadNetThing(std::string url) override {
            preload_urls.push_back(std::move(url));
            return next_task_id++;
        }

        [[nodiscard]] int postNetText(std::string url, std::string post_data) override {
            post_urls.push_back(std::move(url));
            post_bodies.push_back(std::move(post_data));
            return next_task_id++;
        }

        [[nodiscard]] bool netDone(std::optional<int> task_id = std::nullopt) const override {
            last_queried_task = task_id;
            return true;
        }

        [[nodiscard]] std::string netTextResult(std::optional<int> task_id = std::nullopt) const override {
            last_queried_task = task_id;
            return "OVERRIDE";
        }

        [[nodiscard]] int netError(std::optional<int> task_id = std::nullopt) const override {
            last_queried_task = task_id;
            return 0;
        }

        [[nodiscard]] std::string_view getStreamStatus(std::optional<int> task_id = std::nullopt) const override {
            last_queried_task = task_id;
            return "Complete";
        }

        [[nodiscard]] Datum getStreamStatusDatum(std::optional<int> task_id = std::nullopt) const override {
            last_queried_task = task_id;
            auto props = Datum::propList();
            props.propListValue().put(Datum::of(std::string("state")), Datum::of(std::string("Override")));
            props.propListValue().put(Datum::of(std::string("bytesSoFar")), Datum::of(8));
            return props;
        }

        [[nodiscard]] Datum getStreamStatusDatum(std::string_view url) const override {
            last_queried_url = std::string(url);
            auto props = Datum::propList();
            props.propListValue().put(Datum::of(std::string("state")), Datum::of(std::string("OverrideUrl")));
            props.propListValue().put(Datum::of(std::string("bytesSoFar")), Datum::of(9));
            return props;
        }

        std::vector<std::string> preload_urls;
        std::vector<std::string> post_urls;
        std::vector<std::string> post_bodies;
        mutable std::optional<int> last_queried_task;
        mutable std::string last_queried_url;
        int next_task_id = 700;
    };

