    class BuiltinRecordingAudioBackend final : public AudioBackend {
    public:
        void play(int channel_num,
                  const std::vector<std::uint8_t>& audio_data,
                  std::string_view format,
                  int loop_count) override {
            ++play_count;
            last_play_channel = channel_num;
            last_audio_data = audio_data;
            last_format = std::string(format);
            last_loop_count = loop_count;
            playing[channel_num] = true;
        }

        void stop(int channel_num) override {
            ++stop_count;
            last_stop_channel = channel_num;
            playing[channel_num] = false;
        }

        void stopAll() override {
            playing.clear();
        }

        void setVolume(int channel_num, int volume) override {
            ++set_volume_count;
            last_volume_channel = channel_num;
            last_volume = volume;
        }

        [[nodiscard]] bool isPlaying(int channel_num) const override {
            const auto found = playing.find(channel_num);
            return found != playing.end() && found->second;
        }

        [[nodiscard]] int getElapsedTime(int channel_num) const override {
            const auto found = elapsed_times.find(channel_num);
            return found == elapsed_times.end() ? 0 : found->second;
        }

        int play_count{0};
        int stop_count{0};
        int set_volume_count{0};
        int last_play_channel{0};
        int last_stop_channel{0};
        int last_volume_channel{0};
        int last_volume{0};
        int last_loop_count{0};
        std::vector<std::uint8_t> last_audio_data;
        std::string last_format;
        std::map<int, bool> playing;
        std::map<int, int> elapsed_times;
    };

