    assert(run_sprite_collision_opcode(Opcode::INTO_SPR, Datum::spriteRef(ChannelId(72)), Datum::of(70)).boolValue());
    assert(!run_sprite_collision_opcode(Opcode::INTO_SPR, Datum::of(70), Datum::of(72)).boolValue());
