    class RecordingTraceListener final : public TraceListener {
    public:
        struct VariableSet {
            std::string type;
            std::string name;
            Datum value;
        };

        explicit RecordingTraceListener(bool instructions = true)
            : instructions_(instructions) {}

        void onHandlerEnter(const HandlerInfo& info) override {
            events.push_back("enter:" + info.handler_name);
            handler_entries.push_back(info);
        }

        void onHandlerExit(const HandlerInfo& info, const Datum& return_value) override {
            events.push_back("exit:" + info.handler_name);
            handler_exits.push_back(info);
            return_values.push_back(return_value);
        }

        void onInstruction(const InstructionInfo& info) override {
            instructions.push_back(info);
        }

        bool needsInstructionTrace() const override {
            return instructions_;
        }

        void onVariableSet(std::string_view type, std::string_view name, const Datum& value) override {
            variable_sets.push_back(VariableSet{std::string(type), std::string(name), value});
        }

        void onError(std::string_view message, std::string_view error) override {
            errors.emplace_back(std::string(message), std::string(error));
        }

        bool instructions_;
        std::vector<std::string> events;
        std::vector<HandlerInfo> handler_entries;
        std::vector<HandlerInfo> handler_exits;
        std::vector<InstructionInfo> instructions;
        std::vector<VariableSet> variable_sets;
        std::vector<Datum> return_values;
        std::vector<std::pair<std::string, std::string>> errors;
    };

