    auto make_text_rifx = [&](const std::vector<std::pair<std::string, std::vector<std::uint8_t>>>& chunk_list) {
        const int local_mmap_len = 24 + static_cast<int>(chunk_list.size()) * 20;
        int local_data_start = mmap_offset + 8 + local_mmap_len;
        std::vector<int> local_chunk_data_starts;
        local_chunk_data_starts.reserve(chunk_list.size());
        for (const auto& chunk : chunk_list) {
            local_chunk_data_starts.push_back(local_data_start);
            local_data_start += static_cast<int>(chunk.second.size());
        }

        std::vector<std::uint8_t> data;
        append_four_cc(data, "RIFX");
        append_i32(data, 0);
        append_four_cc(data, "MV93");
        append_four_cc(data, "imap");
        append_i32(data, 12);
        append_i32(data, 1);
        append_i32(data, mmap_offset);
        append_i32(data, 0x04B1);
        append_four_cc(data, "mmap");
        append_i32(data, static_cast<std::uint32_t>(local_mmap_len));
        append_i16(data, 24);
        append_i16(data, 20);
        append_i32(data, static_cast<std::uint32_t>(chunk_list.size()));
        append_i32(data, static_cast<std::uint32_t>(chunk_list.size()));
        append_i32(data, 0);
        append_i32(data, 0);
        append_i32(data, 0);
        for (std::size_t index = 0; index < chunk_list.size(); ++index) {
            append_i32(data, BinaryReader::fourCC(chunk_list[index].first));
            append_i32(data, static_cast<std::uint32_t>(chunk_list[index].second.size()));
            append_i32(data, static_cast<std::uint32_t>(local_chunk_data_starts[index] - 8));
            append_i16(data, 0);
            append_i16(data, 0);
            append_i32(data, 0);
        }
        for (const auto& chunk : chunk_list) {
            data.insert(data.end(), chunk.second.begin(), chunk.second.end());
        }
        put_i32_at(data, 4, static_cast<std::uint32_t>(data.size() - 8));
        return data;
    };

