    auto baked_file_xmed = file_xmed_baker.bake(file_xmed_sprite);
    assert(file_xmed_renderer.last_text == "Xmed text");
    assert(file_xmed_renderer.last_width == 11);
    assert(file_xmed_renderer.last_height == 4);
    assert(file_xmed_renderer.last_font_name == "Geneva");
    assert(file_xmed_renderer.last_font_size == 12);
    assert(file_xmed_renderer.last_alignment == "center");
    assert(file_xmed_renderer.last_text_color == static_cast<int>(0xFF112233U));
    assert(file_xmed_renderer.last_bg_color == static_cast<int>(0xFF112233U));
    assert(file_xmed_renderer.last_word_wrap);
    assert(file_xmed_renderer.last_antialias);
    assert(baked_file_xmed.width() == 11);
    assert(baked_file_xmed.height() == 4);
    assert(baked_file_xmed.bakedBitmap()->getPixel(10, 3) == 0xFFABCDEFU);

    std::vector<std::uint8_t> white_xmed_data = xmed_data;
    bool removed_xmed_color_section = false;
    for (std::size_t i = 0; i + 4 < white_xmed_data.size(); ++i) {
        if (white_xmed_data[i] == 0x03 &&
            white_xmed_data[i + 1] == '0' && white_xmed_data[i + 2] == '0' &&
            white_xmed_data[i + 3] == '0' && white_xmed_data[i + 4] == '3') {
            white_xmed_data[i + 4] = 'X';
            removed_xmed_color_section = true;
            break;
        }
    }
    assert(removed_xmed_color_section);
    auto white_xmed_file = DirectorFile::load(make_text_rifx({
        {"DRCF", text_config_data},
        {"CAS*", xmed_cast_data},
        {"CASt", make_cast_member_data(MemberType::Xtra, xmed_specific_data)},
        {"KEY*", xmed_key_data},
        {"XMED", white_xmed_data}
    }));
    auto white_xmed_member = white_xmed_file->castMembers().front();
    auto parsed_white_xmed = white_xmed_file->getXmedStyledTextForMember(white_xmed_member);
    assert(parsed_white_xmed.has_value());
    assert(parsed_white_xmed->textColorARGB() == 0xFFFFFFFFU);

    RecordingSpriteBakerTextRenderer transparent_white_xmed_renderer;
    SpriteBaker transparent_white_xmed_baker;
