    assert(xmed_manager.getMemberProp(1, copied_xmed_text_ref->memberNum(), "font").stringValue() == "Geneva");
    assert(xmed_manager.getMemberProp(1, copied_xmed_text_ref->memberNum(), "fontSize").intValue() == 12);
    assert(xmed_manager.getMemberProp(1, copied_xmed_text_ref->memberNum(), "alignment").asSymbol()->name == "center");
    assert(xmed_manager.getMemberProp(1, copied_xmed_text_ref->memberNum(), "color").asColorRef()->r == 0x11);
    assert(xmed_manager.getMemberProp(1, copied_xmed_text_ref->memberNum(), "color").asColorRef()->g == 0x22);
