    auto member_playable = SoundManager::convertSoundToPlayable(*member_sound);
    assert(member_playable.has_value());
    assert(SoundManager::detectFormat(*member_playable) == "wav");
    auto shockwave3d_member = std::make_shared<CastMemberChunk>(file.get(),
                                                               ChunkId(8),
                                                               MemberType::Shockwave3D,
                                                               0,
                                                               40,
                                                               std::vector<std::uint8_t>{},
                                                               std::vector<std::uint8_t>(40, 0),
                                                               "3D",
                                                               0,
                                                               0,
                                                               0);
    auto linked_w3d_info = file->getLinkedChunkInfoForMember(shockwave3d_member, BinaryReader::fourCC("XMED"));
