    class ManagerMethodTextRenderer final : public TextRenderer {
    public:
        int char_calls = 0;
        int loc_calls = 0;
        std::string last_text;
        int last_char_index = 0;
        int last_x = 0;
        int last_y = 0;
        std::string last_font;
        int last_font_size = 0;
        std::string last_font_style;
        int last_fixed_line_space = 0;
        std::string last_alignment;
        int last_field_width = 0;
        int render_calls = 0;
        int last_render_width = 0;
        int last_render_height = 0;

        std::shared_ptr<Bitmap> renderText(std::string,
                                           int width,
                                           int height,
                                           std::string,
                                           int,
                                           std::string,
                                           std::string,
                                           int,
                                           int,
                                           bool,
                                           bool,
                                           int,
                                           int) override {
            ++render_calls;
            last_render_width = width;
            last_render_height = height;
            auto rendered = std::make_shared<Bitmap>(std::max(1, width), height == 0 ? 44 : height, 32);
            rendered->fill(0xFFEEDDCCU);
            rendered->setPixel(0, 0, 0x00000000U);
            return rendered;
        }

        std::vector<int> charPosToLoc(std::string text,
                                      int char_index,
                                      std::string font_name,
                                      int font_size,
                                      std::string font_style,
                                      int fixed_line_space,
                                      std::string alignment,
                                      int field_width) override {
            ++char_calls;
            last_text = std::move(text);
            last_char_index = char_index;
            last_font = std::move(font_name);
            last_font_size = font_size;
            last_font_style = std::move(font_style);
            last_fixed_line_space = fixed_line_space;
            last_alignment = std::move(alignment);
            last_field_width = field_width;
            return {123, 45};
        }

        int locToCharPos(std::string text,
                         int x,
                         int y,
                         std::string font_name,
                         int font_size,
                         std::string font_style,
                         int fixed_line_space,
                         std::string alignment,
                         int field_width) override {
            ++loc_calls;
            last_text = std::move(text);
            last_x = x;
            last_y = y;
            last_font = std::move(font_name);
            last_font_size = font_size;
            last_font_style = std::move(font_style);
            last_fixed_line_space = fixed_line_space;
            last_alignment = std::move(alignment);
            last_field_width = field_width;
            return 77;
        }

        int getLineHeight(std::string, int font_size, std::string, int fixed_line_space) override {
            return fixed_line_space > 0 ? fixed_line_space : font_size;
        }
    };

