void testBitmapResolverFoundation() {
    auto append_four_cc = [](std::vector<std::uint8_t>& data, const std::string& value) {
        data.insert(data.end(), value.begin(), value.end());
    };
    auto append_i16 = [](std::vector<std::uint8_t>& data, int value) {
        const auto raw = static_cast<std::uint16_t>(value);
        data.push_back(static_cast<std::uint8_t>((raw >> 8) & 0xFF));
        data.push_back(static_cast<std::uint8_t>(raw & 0xFF));
    };
    auto append_i32 = [](std::vector<std::uint8_t>& data, std::uint32_t value) {
        data.push_back(static_cast<std::uint8_t>((value >> 24) & 0xFF));
        data.push_back(static_cast<std::uint8_t>((value >> 16) & 0xFF));
        data.push_back(static_cast<std::uint8_t>((value >> 8) & 0xFF));
        data.push_back(static_cast<std::uint8_t>(value & 0xFF));
    };
    auto put_i16_at = [](std::vector<std::uint8_t>& data, int offset, int value) {
        const auto raw = static_cast<std::uint16_t>(value);
        data[static_cast<std::size_t>(offset)] = static_cast<std::uint8_t>((raw >> 8) & 0xFF);
        data[static_cast<std::size_t>(offset + 1)] = static_cast<std::uint8_t>(raw & 0xFF);
    };
    auto put_i32_at = [](std::vector<std::uint8_t>& data, int offset, std::uint32_t value) {
        data[static_cast<std::size_t>(offset)] = static_cast<std::uint8_t>((value >> 24) & 0xFF);
        data[static_cast<std::size_t>(offset + 1)] = static_cast<std::uint8_t>((value >> 16) & 0xFF);
        data[static_cast<std::size_t>(offset + 2)] = static_cast<std::uint8_t>((value >> 8) & 0xFF);
        data[static_cast<std::size_t>(offset + 3)] = static_cast<std::uint8_t>(value & 0xFF);
    };

    std::vector<std::uint8_t> config_data(80, 0);
    put_i16_at(config_data, 2, 0x0207);
    put_i16_at(config_data, 8, 1);
    put_i16_at(config_data, 10, 2);
    put_i16_at(config_data, 36, 0x0207);
    put_i16_at(config_data, 54, 15);
    put_i16_at(config_data, 78, Palette::RAINBOW);

    std::vector<std::uint8_t> key_data;
    append_i16(key_data, 12);
    append_i16(key_data, 12);
    append_i32(key_data, 1);
    append_i32(key_data, 1);
    append_i32(key_data, 2);
    append_i32(key_data, 9);
    append_i32(key_data, BinaryReader::fourCC("BITD"));

    const std::vector<std::uint8_t> bitd_data{0, 1};
    auto build_rifx = [&](const std::vector<std::pair<std::string, std::vector<std::uint8_t>>>& chunks) {
        constexpr int mmap_offset = 32;
        const int mmap_payload_length = 24 + static_cast<int>(chunks.size()) * 20;
        int payload_start = mmap_offset + 8 + mmap_payload_length;

        std::vector<int> offsets;
        offsets.reserve(chunks.size());
        for (const auto& chunk : chunks) {
            offsets.push_back(payload_start - 8);
            payload_start += static_cast<int>(chunk.second.size());
        }

        std::vector<std::uint8_t> data;
        append_four_cc(data, "RIFX");
        append_i32(data, 0);
        append_four_cc(data, "MV93");
        append_four_cc(data, "imap");
        append_i32(data, 12);
        append_i32(data, 1);
        append_i32(data, mmap_offset);
        append_i32(data, 0x0207);
        append_four_cc(data, "mmap");
        append_i32(data, static_cast<std::uint32_t>(mmap_payload_length));
        append_i16(data, 24);
        append_i16(data, 20);
        append_i32(data, static_cast<std::uint32_t>(chunks.size()));
        append_i32(data, static_cast<std::uint32_t>(chunks.size()));
        append_i32(data, 0);
        append_i32(data, 0);
        append_i32(data, 0);
        for (int index = 0; index < static_cast<int>(chunks.size()); ++index) {
            append_i32(data, BinaryReader::fourCC(chunks[static_cast<std::size_t>(index)].first));
            append_i32(data, static_cast<std::uint32_t>(chunks[static_cast<std::size_t>(index)].second.size()));
            append_i32(data, static_cast<std::uint32_t>(offsets[static_cast<std::size_t>(index)]));
            append_i16(data, 0);
            append_i16(data, 0);
            append_i32(data, 0);
        }
        for (const auto& chunk : chunks) {
            data.insert(data.end(), chunk.second.begin(), chunk.second.end());
        }
        put_i32_at(data, 4, static_cast<std::uint32_t>(data.size() - 8));
        return data;
    };

    auto file = DirectorFile::load(build_rifx({
        {"DRCF", config_data},
        {"KEY*", key_data},
        {"BITD", bitd_data},
    }));
    CastLibManager manager(file);
    FrameContext frame_context(file.get());
    BitmapResolver resolver(file, &manager, &frame_context);

    assert(resolver.file() == file);
    assert(resolver.getMoviePalette().get() == &Palette::rainbowPalette());
    assert(resolver.resolvePaletteByMember(1, 42).get() == &Palette::systemMacPalette());
    assert(manager.resolvePaletteByMember(1, 42).get() == &Palette::systemMacPalette());

    std::vector<std::uint8_t> bitmap_specific;
    append_i16(bitmap_specific, 2);
    append_i16(bitmap_specific, 0);
    append_i16(bitmap_specific, 0);
    append_i16(bitmap_specific, 1);
    append_i16(bitmap_specific, 2);
    bitmap_specific.insert(bitmap_specific.end(), 8, 0);
    append_i16(bitmap_specific, 0);
    append_i16(bitmap_specific, 0);
    bitmap_specific.push_back(0);
    bitmap_specific.push_back(8);
    append_i16(bitmap_specific, 1);
    auto bitmap_member = std::make_shared<CastMemberChunk>(file.get(),
                                                          ChunkId(9),
                                                          MemberType::Bitmap,
                                                          0,
                                                          static_cast<int>(bitmap_specific.size()),
                                                          std::vector<std::uint8_t>{},
                                                          bitmap_specific,
                                                          "Bitmap",
                                                          0,
                                                          0,
                                                          0);

    auto decoded = resolver.decodeBitmap(bitmap_member);
    assert(decoded.has_value());
    assert(decoded->width() == 2);
    assert(decoded->height() == 1);
    assert(decoded->bitDepth() == 8);
    assert(decoded->getPixel(0, 0) == 0xFFFFFFFFU);
    assert(decoded->getPixel(1, 0) == 0xFFFFFFCCU);
    assert(decoded->paletteIndex(1, 0).value() == 1);
    assert(decoded->imagePalette().get() == &Palette::systemMacPalette());

    auto windows_host_config_data = config_data;
    put_i16_at(windows_host_config_data, 56, 2);
    auto windows_host_file = DirectorFile::load(build_rifx({
        {"DRCF", windows_host_config_data},
        {"KEY*", key_data},
        {"BITD", bitd_data},
    }));
    auto external_bitmap_file = DirectorFile::load(build_rifx({
        {"DRCF", config_data},
        {"KEY*", key_data},
        {"BITD", bitd_data},
    }));
    auto external_bitmap_member = std::make_shared<CastMemberChunk>(external_bitmap_file.get(),
                                                                    ChunkId(9),
                                                                    MemberType::Bitmap,
                                                                    0,
                                                                    static_cast<int>(bitmap_specific.size()),
                                                                    std::vector<std::uint8_t>{},
                                                                    bitmap_specific,
                                                                    "External Bitmap",
                                                                    0,
                                                                    0,
                                                                    0);
    BitmapResolver external_bitmap_resolver(windows_host_file);
    auto external_decoded = external_bitmap_resolver.decodeBitmap(external_bitmap_member);
    assert(external_decoded.has_value());
    assert(external_decoded->imagePalette().get() == &Palette::systemWinPalette());
    assert(external_decoded->getPixel(1, 0) == (0xFF000000U | Palette::systemWinPalette().getColor(1)));

    Palette override_palette({0x010203U, 0x040506U}, "override");
    auto overridden = resolver.decodeBitmap(bitmap_member, &override_palette);
    assert(overridden.has_value());
    assert(overridden->getPixel(0, 0) == 0xFF010203U);
    assert(overridden->getPixel(1, 0) == 0xFF040506U);
    assert(overridden->imagePalette().get() == &override_palette);

    auto provider_bitmap = resolver.decodeBitmapForProvider(*bitmap_member, &override_palette);
    assert(provider_bitmap != nullptr);
    assert(provider_bitmap->getPixel(1, 0) == 0xFF040506U);

    std::vector<std::uint8_t> unrelated_palette_data;
    for (const auto color : std::vector<std::uint32_t>{0x010203U, 0x102030U}) {
        const int red = static_cast<int>((color >> 16U) & 0xFFU);
        const int green = static_cast<int>((color >> 8U) & 0xFFU);
        const int blue = static_cast<int>(color & 0xFFU);
        unrelated_palette_data.insert(unrelated_palette_data.end(), {
            static_cast<std::uint8_t>(red),
            static_cast<std::uint8_t>(red),
            static_cast<std::uint8_t>(green),
            static_cast<std::uint8_t>(green),
            static_cast<std::uint8_t>(blue),
            static_cast<std::uint8_t>(blue)
        });
    }
    std::vector<std::uint8_t> mac_like_palette_data;
    for (const auto color : std::vector<std::uint32_t>{0xFFFFFFU, 0xFFFFAAU}) {
        const int red = static_cast<int>((color >> 16U) & 0xFFU);
        const int green = static_cast<int>((color >> 8U) & 0xFFU);
        const int blue = static_cast<int>(color & 0xFFU);
        mac_like_palette_data.insert(mac_like_palette_data.end(), {
            static_cast<std::uint8_t>(red),
            static_cast<std::uint8_t>(red),
            static_cast<std::uint8_t>(green),
            static_cast<std::uint8_t>(green),
            static_cast<std::uint8_t>(blue),
            static_cast<std::uint8_t>(blue)
        });
    }
    auto file_with_unrelated_palette = DirectorFile::load(build_rifx({
        {"DRCF", config_data},
        {"KEY*", key_data},
        {"BITD", bitd_data},
        {"CLUT", unrelated_palette_data},
        {"CLUT", mac_like_palette_data},
    }));
    std::vector<std::uint8_t> unresolved_palette_specific = bitmap_specific;
    unresolved_palette_specific[unresolved_palette_specific.size() - 2] = 0x03;
    unresolved_palette_specific[unresolved_palette_specific.size() - 1] = 0xE7;
    auto unresolved_palette_bitmap_member = std::make_shared<CastMemberChunk>(
        file_with_unrelated_palette.get(),
        ChunkId(9),
        MemberType::Bitmap,
        0,
        static_cast<int>(unresolved_palette_specific.size()),
        std::vector<std::uint8_t>{},
        unresolved_palette_specific,
        "Unresolved Palette Bitmap",
        0,
        0,
        0);
    auto unresolved_palette_decoded = file_with_unrelated_palette->decodeBitmap(unresolved_palette_bitmap_member);
    assert(unresolved_palette_decoded.has_value());
    assert(unresolved_palette_decoded->getPixel(0, 0) == 0xFFFFFFFFU);
    assert(unresolved_palette_decoded->getPixel(1, 0) == 0xFFFFFFAAU);
    assert(unresolved_palette_decoded->imagePalette().get() != &Palette::systemMacPalette());

    std::vector<std::uint8_t> sidecar_key_data;
    append_i16(sidecar_key_data, 12);
    append_i16(sidecar_key_data, 12);
    append_i32(sidecar_key_data, 2);
    append_i32(sidecar_key_data, 2);
    append_i32(sidecar_key_data, 2);
    append_i32(sidecar_key_data, 10);
    append_i32(sidecar_key_data, BinaryReader::fourCC("ediM"));
    append_i32(sidecar_key_data, 3);
    append_i32(sidecar_key_data, 10);
    append_i32(sidecar_key_data, BinaryReader::fourCC("ALFA"));

    const std::vector<std::uint8_t> jpeg_data{0xFF, 0xD8, 0xFF, 0xD9};
    const std::vector<std::uint8_t> alfa_data{0x01, 0x40, 0x80};
    auto sidecar_file = DirectorFile::load(build_rifx({
        {"DRCF", config_data},
        {"KEY*", sidecar_key_data},
        {"ediM", jpeg_data},
        {"ALFA", alfa_data},
    }));

    std::vector<std::uint8_t> sidecar_specific;
    append_i16(sidecar_specific, 8);
    append_i16(sidecar_specific, 0);
    append_i16(sidecar_specific, 0);
    append_i16(sidecar_specific, 1);
    append_i16(sidecar_specific, 2);
    sidecar_specific.insert(sidecar_specific.end(), 8, 0);
    append_i16(sidecar_specific, 0);
    append_i16(sidecar_specific, 0);
    sidecar_specific.push_back(0);
    sidecar_specific.push_back(32);
    append_i16(sidecar_specific, 1);
    auto sidecar_member = std::make_shared<CastMemberChunk>(sidecar_file.get(),
                                                           ChunkId(10),
                                                           MemberType::Bitmap,
                                                           0,
                                                           static_cast<int>(sidecar_specific.size()),
                                                           std::vector<std::uint8_t>{},
                                                           sidecar_specific,
                                                           "ediM Bitmap",
                                                           0,
                                                           0,
                                                           0);

    DirectorFile::setJpegDecoder(DirectorFile::JpegDecoder{});
    assert(!sidecar_file->decodeBitmap(sidecar_member).has_value());
    DirectorFile::clearJpegDecodePending();
    assert(!DirectorFile::consumeJpegDecodePending());
    DirectorFile::markJpegDecodePending();
    assert(DirectorFile::consumeJpegDecodePending());
    assert(!DirectorFile::consumeJpegDecodePending());

    int jpeg_decoder_calls = 0;
    std::vector<std::uint8_t> captured_jpeg_data;
    DirectorFile::setJpegDecoder([&](const std::vector<std::uint8_t>& data) -> std::optional<Bitmap> {
        ++jpeg_decoder_calls;
        captured_jpeg_data = data;
        return Bitmap(2, 1, 32, {0xFF102030U, 0xFF405060U});
    });

    auto sidecar_decoded = sidecar_file->decodeBitmap(sidecar_member);
    assert(sidecar_decoded.has_value());
    assert(jpeg_decoder_calls == 1);
    assert(captured_jpeg_data == jpeg_data);
    assert(sidecar_decoded->width() == 2);
    assert(sidecar_decoded->height() == 1);
    assert(sidecar_decoded->bitDepth() == 32);
    assert(sidecar_decoded->isNativeAlpha());
    assert(sidecar_decoded->getPixel(0, 0) == 0x40102030U);
    assert(sidecar_decoded->getPixel(1, 0) == 0x80405060U);
    DirectorFile::setJpegDecoder(DirectorFile::JpegDecoder{});

    BitmapResolver empty_resolver;
    assert(!empty_resolver.getMoviePalette());
    assert(!empty_resolver.decodeBitmap(nullptr).has_value());
}

void testLookupHelpers() {
    auto cast = std::make_shared<CastChunk>(nullptr, ChunkId(80), std::vector<int>{41, 42});
    auto member5 = std::make_shared<CastMemberChunk>(nullptr,
                                                     ChunkId(5),
                                                     MemberType::Bitmap,
                                                     0,
                                                     0,
                                                     std::vector<std::uint8_t>{},
                                                     std::vector<std::uint8_t>{},
                                                     "",
                                                     0,
                                                     0,
                                                     0);
    auto member42 = std::make_shared<CastMemberChunk>(nullptr,
                                                      ChunkId(42),
                                                      MemberType::Bitmap,
                                                      0,
                                                      0,
                                                      std::vector<std::uint8_t>{},
                                                      std::vector<std::uint8_t>{},
                                                      "",
                                                      0,
                                                      0,
                                                      0);
    CastListChunk::CastListEntry entry{"Internal", "", 0, 5, 6, 2, 1};
    auto cast_list = std::make_shared<CastListChunk>(nullptr, ChunkId(81), 0, 4, 1, std::vector<CastListChunk::CastListEntry>{entry});
    CastMemberLookup cast_lookup({cast}, {member5, member42}, cast_list, nullptr);
    assert(cast_lookup.getMappedCast(1) == cast);
    assert(cast_lookup.getByIndex(1, 0) == member5);
    assert(cast_lookup.getByNumber(1, 6) == member42);
    assert(cast_lookup.getByNumber(1, 5) == nullptr);

    auto script = std::make_shared<ScriptChunk>(nullptr,
                                                ChunkId(200),
                                                ScriptChunkType::Behavior,
                                                0,
                                                std::vector<ScriptChunk::Handler>{},
                                                std::vector<ScriptChunk::LiteralEntry>{},
                                                std::vector<ScriptChunk::PropertyEntry>{},
                                                std::vector<ScriptChunk::GlobalEntry>{},
                                                std::vector<std::uint8_t>{});
    ScriptContextChunk::ScriptEntry script_entry{0, ChunkId(200), 0};
    auto context = std::make_shared<ScriptContextChunk>(nullptr,
                                                        ChunkId(201),
                                                        0,
                                                        0,
                                                        1,
                                                        ChunkId(202),
                                                        1,
                                                        0,
                                                        0,
                                                        std::vector<ScriptContextChunk::ScriptEntry>{script_entry});
    auto script_member = std::make_shared<CastMemberChunk>(nullptr,
                                                          ChunkId(203),
                                                          MemberType::Script,
                                                          0,
                                                          2,
                                                          std::vector<std::uint8_t>{},
                                                          std::vector<std::uint8_t>{0, 2},
                                                          "Behavior",
                                                          1,
                                                          0,
                                                          0);
    ScriptLookup script_lookup({script}, {context}, {script_member});
    assert(script_lookup.getByContextId(1) == script);
    assert(script_lookup.getAllByContextId(1).size() == 1);
    assert(script_lookup.getByContextId(99) == nullptr);
    assert(script_lookup.getScriptType(script).has_value());
    assert(script_lookup.getScriptType(script).value() == CastMemberScriptType::Behavior);

    std::vector<std::uint32_t> custom_colors(256, 0);
    custom_colors[0] = 0x112233U;
    custom_colors[1] = 0x445566U;
    const auto system_mac_tail = Palette::systemMacPalette().getColor(248);
    assert(system_mac_tail != 0);
    auto palette_chunk = std::make_shared<PaletteChunk>(nullptr, ChunkId(91), custom_colors);
    auto palette_member = std::make_shared<CastMemberChunk>(nullptr,
                                                           ChunkId(90),
                                                           MemberType::Palette,
                                                           0,
                                                           0,
                                                           std::vector<std::uint8_t>{},
                                                           std::vector<std::uint8_t>{},
                                                           "Palette",
                                                           0,
                                                           0,
                                                           0);
    auto palette_cast = std::make_shared<CastChunk>(nullptr, ChunkId(92), std::vector<int>{0, 90});
    CastListChunk::CastListEntry palette_entry{"PaletteLib", "", 0, 10, 11, 2, 1};
    auto palette_cast_list = std::make_shared<CastListChunk>(
        nullptr, ChunkId(93), 0, 4, 1, std::vector<CastListChunk::CastListEntry>{palette_entry});
    auto palette_key = std::make_shared<KeyTableChunk>(
        nullptr,
        ChunkId(94),
        std::vector<KeyTableChunk::KeyTableEntry>{
            KeyTableChunk::KeyTableEntry{ChunkId(91), ChunkId(90), BinaryReader::fourCC("CLUT")}
        });
    PaletteResolver palette_resolver(
        {palette_cast},
        {palette_member},
        {palette_chunk},
        palette_cast_list,
        nullptr,
        palette_key,
        [palette_chunk](ChunkId id) -> std::shared_ptr<libreshockwave::chunks::Chunk> {
            return id.value() == palette_chunk->id().value() ? palette_chunk : nullptr;
        });
    assert(palette_resolver.resolve(Palette::RAINBOW).get() == &Palette::rainbowPalette());

    auto resolved_by_member_number = palette_resolver.resolveExact(10);
    assert(resolved_by_member_number.get() != nullptr);
    assert(resolved_by_member_number->getColor(0) == 0x112233U);
    assert(resolved_by_member_number->getColor(1) == 0x445566U);
    assert(resolved_by_member_number->getColor(248) == system_mac_tail);
    assert(palette_resolver.resolve(10).get() == resolved_by_member_number.get());
    assert(palette_resolver.resolveExact(90).get() == resolved_by_member_number.get());
    assert(palette_resolver.resolveExact(91).get() == resolved_by_member_number.get());

    PaletteResolver indexed_palette_resolver(
        {},
        {palette_member},
        {palette_chunk},
        nullptr,
        nullptr,
        palette_key,
        [palette_chunk](ChunkId id) -> std::shared_ptr<libreshockwave::chunks::Chunk> {
            return id.value() == palette_chunk->id().value() ? palette_chunk : nullptr;
        });
    assert(indexed_palette_resolver.resolveExact(0)->getColor(0) == 0x112233U);
    assert(palette_resolver.resolveExact(999).get() == nullptr);
    assert(palette_resolver.resolve(999)->getColor(0) == 0x112233U);

    PaletteResolver empty_palette_resolver({}, {}, {}, nullptr, nullptr, nullptr, {});
    assert(empty_palette_resolver.resolveExact(999).get() == nullptr);
    assert(empty_palette_resolver.resolve(999).get() == &Palette::systemMacPalette());

    DirectorFile empty_file(ByteOrder::BigEndian, false, 0, ChunkType::MV93);
    assert(empty_file.stageWidth() == 0);
    assert(empty_file.stageHeight() == 0);
    assert(empty_file.channelCount() == 120);
    assert(empty_file.tempo() == 15);
    assert(empty_file.getScoreTempo(0) == -1);
    assert(!empty_file.getScorePalette(0).has_value());
    assert(empty_file.getScriptForCastMember(nullptr).get() == nullptr);
    assert(!empty_file.getScriptType(nullptr).has_value());
    assert(empty_file.getScriptName(nullptr).empty());
    assert(empty_file.getScriptNamesById(ChunkId(1)).get() == nullptr);
    assert(empty_file.getScriptNamesForScript(nullptr).get() == nullptr);
    assert(empty_file.getAllGlobalNames().empty());
    assert(empty_file.getAllPropertyNames().empty());
    assert(empty_file.getScriptGlobals(nullptr).empty());
    assert(empty_file.getScriptProperties(nullptr).empty());
    assert(empty_file.getScriptInfoList().empty());
    assert(empty_file.getExternalCastPaths().empty());
    assert(!empty_file.hasExternalCasts());
    assert(!empty_file.hasScore());
    assert(!empty_file.getFontNameForId(1).has_value());
    assert(empty_file.basePath().empty());
    empty_file.setBasePath("movie-dir");
    assert(empty_file.basePath() == "movie-dir");
    assert(empty_file.resolvePalette(Palette::SYSTEM_WIN).get() == &Palette::systemWinPalette());
    assert(empty_file.resolvePaletteExact(999).get() == nullptr);
    assert(empty_file.resolvePaletteByMemberNumber(42).get() == &Palette::systemMacPalette());
}

